#include <stdio.h>
#include <string.h>

void greet(const char *name) {
    char buffer[16];
    strncpy(buffer, name, sizeof(buffer) - 1);
    buffer[sizeof(buffer) - 1] = '\0';
    printf("Hello, %s!\n", buffer);
}

int main(void) {
    char input[4096];
    if (fgets(input, sizeof(input), stdin) == NULL) {
        return 1;
    }
    size_t len = strlen(input);
    if (len > 0 && input[len - 1] == '\n') {
        input[len - 1] = '\0';
    }
    greet(input);
    return 0;
}
